INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(8401, '1 Kings 7:9', '1 Kings', 7, 9, '&nbsp;ټول عمارتونه او لوئ دربار د بېخ نه د چت لاندې حِصې پورې د ښو کاڼو نه جوړ وو. کاڼى په ناپ پرې کړے شوى وُو، بهرنى او دنننى مخونه يې په آرا برابر کړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8402, '1 Kings 7:10', '1 Kings', 7, 10, '&nbsp;بنيادونه يې د غټو او ښو کاڼو نه جوړ وُو، چې څۀ په کښې پينځۀ ګزه او څۀ څلور ګزه اوږدۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8403, '1 Kings 7:11', '1 Kings', 7, 11, '&nbsp;د دې دپاسه نور ښۀ کاڼى وُو چې په ناپ پرې کړے شوى وُو او د دِيار تيرونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8404, '1 Kings 7:12', '1 Kings', 7, 12, '&nbsp;د محل دربار، د مالِک خُدائ د کور دنننے دربار او دې ته د ننوتو کوټې داسې دېوالونه لرل چې د پرې کړے شوو کاڼو د هرې درېمې ردې نه پس د دِيار يو تير په کښې لګېدلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8405, '1 Kings 7:13', '1 Kings', 7, 13, '&nbsp;سليمان بادشاه يو سړے راوغوښتو چې نوم يې حيرام وو، هغه کاريګر د صور په ښار کښې اوسېدو، چې د زېړو په کار کښې ماهِر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8406, '1 Kings 7:14', '1 Kings', 7, 14, '&nbsp;د هغۀ پلار د صور د علاقې د زېړو ماهِر وو، او مور يې د نفتالى قبيلې يوه کونډه وه. حيرام يو تکړه او تجربه‌کار ماهِر وو. هغۀ د سليمان دعوت قبول کړو چې د زېړو د ټول کار مشر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8407, '1 Kings 7:15', '1 Kings', 7, 15, '&nbsp;حيرام دوه د زېړو ستنې جوړې کړې چې هره يوه تقريباً نهۀ ګزه لوړه او شپږ ګزه ګېرچاپېره غټه وه او دا يې د مالِک خُدائ د کور د ننوتلو په ځائ کښې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8408, '1 Kings 7:16', '1 Kings', 7, 16, '&nbsp;هغۀ د ستنو دپاره دوه د زېړو سرونه هم جوړ کړل، چې هر يو اووۀ نيم فټه لوړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8409, '1 Kings 7:17', '1 Kings', 7, 17, '&nbsp;د هرې ستنې سر د تړلى شوى زنځيرونو په شکلونو باندې ښائسته کړے شوے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8410, '1 Kings 7:18', '1 Kings', 7, 18, '&nbsp;او دوه قطاره د انارو هم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8411, '1 Kings 7:19', '1 Kings', 7, 19, '&nbsp;د ستنې پاسنۍ برخه د نيلوفر د ګل په شان وه چې دوه ګزه لوړه وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8412, '1 Kings 7:20', '1 Kings', 7, 20, '&nbsp;او په يوه ګول حِصه کښې لګولې شوې وه چې دا د زنځير د شکل دپاسه وه. د ستنو په سرونو کښې ګېرچاپېره په دوو قطارونو کښې دوه سوه انار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8413, '1 Kings 7:21', '1 Kings', 7, 21, '&nbsp;حيرام د زېړو دوه ستنې د خُدائ پاک د کور د ننوتو ځائ په مخکښې ولګولې، د جنوب په طرف باندې د هغې نوم يکين وو او چې د شمال په طرف باندې وه د هغې نوم بوعز وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8414, '1 Kings 7:22', '1 Kings', 7, 22, '&nbsp;د ستنو سرونه د نيلوفر د ګلونو په شان وُو. نو داسې د ستنو کار مکمل شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8415, '1 Kings 7:23', '1 Kings', 7, 23, '&nbsp;بيا حيرام د زېړو يوه ګول ډيګۍ جوړه کړه چې تقريباً درې ګزه ډُوبه وه، مينځ يې پينځۀ ګزه وو او ګېرچاپېره غټ والے يې پينځلس ګزه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8416, '1 Kings 7:24', '1 Kings', 7, 24, '&nbsp;د ډيګۍ ګېرچاپېره په بهرنۍ ټوله څنډه باندې دوه قطاره چې په هر فُټ کښې شپږ شپږ د زېړو کدوان وُو، چې د ټولې ډيګۍ سره يوه توکړه جوړه شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8417, '1 Kings 7:25', '1 Kings', 7, 25, '&nbsp;ډيګۍ د زېړو دولسو غوَيانو په شا باندې پراته وه چې مخونه يې بهر وُو، چې په څلورو طرفونو باندې درې درې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8418, '1 Kings 7:26', '1 Kings', 7, 26, '&nbsp;د ډيګۍ دېوالونه درې اِنچۍ غټ وُو. د دې څنډه د پيالۍ د څنډې په شان وه، چې د نيلوفر د ګلونو پاڼو په شان ښکارېده. په ډيګۍ کښې تقريباً څلوېښت زره ليټره اوبۀ راتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8419, '1 Kings 7:27', '1 Kings', 7, 27, '&nbsp;حيرام د زېړو لس ګاډۍ هم جوړې کړې، چې هره يوه تقريباً دوه ګزه اوږده، دوه ګزه پلنه او يو نيم ګز اوچته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8420, '1 Kings 7:28', '1 Kings', 7, 28, '&nbsp;دا د څلور ګوټه تختو نه جوړې وې چې په چوکاټونو کښې لګولے شوې وې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8421, '1 Kings 7:29', '1 Kings', 7, 29, '&nbsp;چې په دې تختو باندې د زمرو، غوَيانو او د وزرو والا مخلوق نمونې جوړ وُو، په چوکاټونو باندې بره او لاندې ګول ګُلکارى شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8422, '1 Kings 7:30', '1 Kings', 7, 30, '&nbsp;د هرې ګاډۍ څلور د زېړو پايې او د زېړو سيخونه وُو. په هره ګاډۍ کښې يو ښانک د زېړو په څلورو تختو باندې لګېدلے وو، دا چوکۍ په ګول ګُلکارۍ باندې ښائسته کړے شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8423, '1 Kings 7:31', '1 Kings', 7, 31, '&nbsp;د هرې ګاډۍ په سر د ښانک دپاره يو ګول چوکاټ وو. دا د ګاډۍ په سر اتلس اِنچې بره او اووۀ اِنچې لاندې تلے وو او ګېرچاپېره ګُلکارى ورباندې شوې وه. د ګاډو تختې ګول نۀ بلکې څلور ګوټه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8424, '1 Kings 7:32', '1 Kings', 7, 32, '&nbsp;څلور پايې شپږويشت اِنچې اوچتې وې، دا د تختو لاندې وې او سيخونه د ګاډو سره يوه ټُکړه شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8425, '1 Kings 7:33', '1 Kings', 7, 33, '&nbsp;د دې پايې د جنګى ګاډو د پايو په شان وې، د دې سيخونه، ريمونه، د ريمونو تيلۍ او مينځنۍ حِصې هر څۀ د زېړو وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8426, '1 Kings 7:34', '1 Kings', 7, 34, '&nbsp;د هرې ګاډۍ په څلورو ګوټونو کښې څلور ستنې وې، چې د ګاډۍ سره يوه ټُکړه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8427, '1 Kings 7:35', '1 Kings', 7, 35, '&nbsp;د هرې ګاډۍ دپاسه ګېرچاپېره نهۀ اِنچې پلنې پټۍ وې، د دې ستنې او تختې د ګاډۍ سره يوه ټُکړه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8428, '1 Kings 7:36', '1 Kings', 7, 36, '&nbsp;ستنې او تختې د وزرو والا مخلوق، زمرو او د کجورو ونو په شکلونو باندې ښائسته کړے شوې وې، چې چرته هم خالى ځائ وو نو ګول ګُلکارى ورباندې شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8429, '1 Kings 7:37', '1 Kings', 7, 37, '&nbsp;لس واړه ګاډۍ داسې جوړې کړے شوې وې چې ټولې يو شان، په يو ناپ او يو شکل وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8430, '1 Kings 7:38', '1 Kings', 7, 38, '&nbsp;حيرام د لسو ګاډو دپاره يو يو ښانک جوړ کړو. چې د هر يو مينځ تقريباً دوه ګزه وو او اتۀ سوه ليټره اوبۀ په کښې راتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8431, '1 Kings 7:39', '1 Kings', 7, 39, '&nbsp;هغۀ پينځۀ ګاډۍ د خُدائ پاک د کور جنوبى طرف ته ودرولې او نورې پينځۀ يې شمالى طرف ته ودرولې، هغه ډيګۍ يې نمرخاتۀ جنوبى طرف ته کېښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8432, '1 Kings 7:46', '1 Kings', 7, 46, '&nbsp;سليمان بادشاه دا هر څۀ د اُردن په مېدان، د سُکات او د ضرتان په مينځ کښې د خټې په قالب کښې جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8433, '1 Kings 7:47', '1 Kings', 7, 47, '&nbsp;سليمان د زېړو دا څيزونه تللى نۀ وُو، ځکه چې دا ډېر زيات وُو، نو د دې وزن کله هم معلوم نۀ کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8434, '1 Kings 7:48', '1 Kings', 7, 48, '&nbsp;سليمان د مالِک خُدائ د کور دپاره د سرو زرو دا سامان هم جوړ کړو، قربان‌ګاه، خُدائ پاک ته د پېش کړے شوې روټۍ مېز،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8435, '1 Kings 7:49', '1 Kings', 7, 49, '&nbsp;لس ډيوټ چې د زيات مقدس ځائ په مخکښې لګېدلى وُو، چې پينځۀ په جنوبى طرف او پينځۀ په شمالى طرف باندې وُو، ګلونه، ډيوې او چمټې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8436, '1 Kings 7:50', '1 Kings', 7, 50, '&nbsp;پيالۍ، د ډيوو سرپوښونه، جامونه، د خوشبويۍ لوښى او د بلو سکارو د وړلو دپاره لوښى، او د زيات مقدس ځائ د دروازو دپاره قبضې او د مالِک خُدائ د کور بهرنۍ دروازې. دا ټول سامان د سوچه سرو زرو نه جوړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8437, '1 Kings 7:51', '1 Kings', 7, 51, '&nbsp;کله چې سليمان بادشاه د مالِک خُدائ د کور ټول کار ختم کړو، نو هغۀ د مالِک خُدائ دکور په خزانو کښې هغه ټول څيزونه کېښودل چې د هغۀ پلار داؤد مالِک خُدائ ته وقف کړى وُو. يعنې سپين زر، سرۀ زر او نور سامان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8438, '1 Kings 8:1', '1 Kings', 8, 1, '&nbsp;بيا سليمان بادشاه د بنى اِسرائيلو مشران او د ډلو ټول مشران راوغوښتل چې يروشلم ته راشى او د لوظ صندوق د داؤد د ښار صيون نه د مالِک خُدائ کور ته يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8439, '1 Kings 8:2', '1 Kings', 8, 2, '&nbsp;په اوومه يعنې د ايتانيم مياشت هغوئ ټول د سليمان بادشاه په وړاندې د جونګړو د اختر په وخت کښې راغونډ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8440, '1 Kings 8:3', '1 Kings', 8, 3, '&nbsp;کله چې ټول مشران راغونډ وُو، نو اِمامانو د لوظ صندوق اوچت کړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8441, '1 Kings 8:4', '1 Kings', 8, 4, '&nbsp;او د مالِک خُدائ کور ته يې يوړو. ليويانو او اِمامانو د مالِک خُدائ د حضور خېمه او د هغې ټول مقدس سامان هم د مالِک خُدائ کور ته يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8442, '1 Kings 8:5', '1 Kings', 8, 5, '&nbsp;سليمان بادشاه او د بنى اِسرائيلو ټول قوم د لوظ صندوق په وړاندې راغونډ شول او په دومره لوئ شمېر کښې ګډې او څاروى يې قربانى کړل چې د شمېر نه بهر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8443, '1 Kings 8:6', '1 Kings', 8, 6, '&nbsp;بيا اِمامانو د مالِک خُدائ د لوظ صندوق د هغۀ کور ته دننه کړو او په زيات مقدس ځائ کښې يې دننه د وزرو والا مخلوق د وزرو لاندې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8444, '1 Kings 8:7', '1 Kings', 8, 7, '&nbsp;د وزرو والا مخلوق وزر د صندوق او د دې د وړلو بازوګانو دپاسه خوارۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8445, '1 Kings 8:8', '1 Kings', 8, 8, '&nbsp;بازوګان دومره اوږدۀ وُو چې هغه خلقو ته ښکارېدل څوک چې زيات مقدس ځائ ته مخامخ ولاړ وو، خو د بهر نه نۀ ښکارېدل. (هغه بازوګان تر نن ورځې پورې هلته دى.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8446, '1 Kings 8:9', '1 Kings', 8, 9, '&nbsp;د لوظ صندوق کښې دننه د کاڼو هغه دوو تختو نه بغېر هيڅ هم نۀ وُو چې موسىٰ د سينا د غرۀ سره په کښې اېښې وې، په کوم وخت کښې چې بنى اِسرائيل د مِصر مُلک نه راووتل او مالِک خُدائ د هغوئ سره يو لوظ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8447, '1 Kings 8:10', '1 Kings', 8, 10, '&nbsp;چې کله اِمامان د مقدس ځائ نه راوتل، نو د مالِک خُدائ کور د وريځې نه ډک شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8448, '1 Kings 8:11', '1 Kings', 8, 11, '&nbsp;نو اِمامانو د وريځې په وجه خپل خِدمت نۀ شو تر سره کولے ځکه چې د مالِک خُدائ کور د هغۀ د جلال نه ډک شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8449, '1 Kings 8:12', '1 Kings', 8, 12, '&nbsp;بيا سليمان دُعا وغوښته، ”اے مالِکه خُدايه، تا فرمائيلى دى چې تۀ به په تکه توره وريځ کښې موجود يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8450, '1 Kings 8:13', '1 Kings', 8, 13, '&nbsp;خو ما ستا دپاره يو عالى شان کور جوړ کړے دے، يو داسې ځائ چې تل به په کښې اوسېږې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8451, '1 Kings 8:14', '1 Kings', 8, 14, '&nbsp;کله چې د قوم خلق هلته ولاړ وُو، نو سليمان بادشاه مخ ورواړولو او د هغوئ دپاره يې د خُدائ پاک نه برکت وغوښتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8452, '1 Kings 8:15', '1 Kings', 8, 15, '&nbsp;هغۀ وفرمائيل، ”د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک ثناء صِفت دې وى. هغۀ هغه وعده پوره کړه چې زما پلار داؤد سره يې کړې وه، چې کله هغۀ وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8453, '1 Kings 8:16', '1 Kings', 8, 16, '&nbsp;د کوم وخت نه چې ما خپل خلق د مِصر نه راويستلى دى، نو ما د بنى اِسرائيلو په ټول مُلک کښې يو ښار هم نۀ دے خوښ کړے چرته به چې هغه کور جوړيږى چې هلته به زما عبادت کيږى. خو داؤده، زۀ تا خوښوم چې زما په خلقو بادشاهى کوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8454, '1 Kings 8:17', '1 Kings', 8, 17, '&nbsp;او سليمان خپله خبره جارى وساتله، ”زما پلار داؤد دا غوښتل چې د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د عبادت دپاره يو کور جوړ کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8455, '1 Kings 8:18', '1 Kings', 8, 18, '&nbsp;خو مالِک خُدائ هغۀ ته وفرمائيل، چې ستا اراده ښۀ وه چې زما د نوم د درناوى دپاره يو کور جوړ کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8456, '1 Kings 8:19', '1 Kings', 8, 19, '&nbsp;خو تۀ به دا جوړ نۀ کړې. هغه به ستا زوئ، ستا خپل زوئ وى چې زما د نوم دپاره به کور جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8457, '1 Kings 8:20', '1 Kings', 8, 20, '&nbsp;او اوس مالِک خُدائ خپله وعده پوره کړې ده. زۀ د خپل پلار داؤد په ځائ د بنى اِسرائيلو په تخت ناست يم لکه څنګه چې مالِک خُدائ وعده کړې وه او ما د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک د عبادت دپاره هغه کور جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8458, '1 Kings 8:21', '1 Kings', 8, 21, '&nbsp;ما په هغه کور کښې د لوظ صندوق دپاره د يو ځائ بندوبست کړے دے چې په هغې کښې د مالِک خُدائ د تړون هغه تختې پرتې دى چې د کوم لوظ هغۀ زمونږ د پلار نيکۀ سره کړے وو چې کله يې د مِصر نه راوويستل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8459, '1 Kings 8:22', '1 Kings', 8, 22, '&nbsp;نو د بنى اِسرائيلو د قوم په موجودګۍ کښې سليمان لاړو او د مالِک خُدائ د قربان‌ګاه په مخکښې ودرېدو، هلته يې د آسمان طرف ته خپل لاسونه اوچت کړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8460, '1 Kings 8:23', '1 Kings', 8, 23, '&nbsp;او دُعا يې وکړه، ”مالِکه خُدايه، د بنى اِسرائيلو خُدايه پاکه. پاس په آسمان کښې او لاندې په زمکه ستا په شان خُدائ نشته، د خپلو خلقو سره ستا لوظ پوره کړه څوک چې د زړۀ د اخلاصه ستا تابعدارى کوى او هغوئ ته خپله مينه وښايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8461, '1 Kings 8:24', '1 Kings', 8, 24, '&nbsp;تا چې زما پلار داؤد سره کومه وعده کړې وه نو هغه دې پوره کړې ده، نن هره خبره پوره شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8462, '1 Kings 8:25', '1 Kings', 8, 25, '&nbsp;او مالِکه خُدايه د بنى اِسرائيلو خُدايه پاکه، زۀ تا ته سوال کوم چې تۀ به هغه بله وعده هم پوره کړې چې تا زما د پلار سره کړې وه چې کله دې هغۀ ته وفرمائيل چې د هغۀ اولاد نه به همېشه يو کس داسې وى چې په بنى اِسرائيلو به بادشاهى کوى، کۀ د هغۀ اولاد هم د هغۀ په شان صحيح فرمانبردارى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8463, '1 Kings 8:26', '1 Kings', 8, 26, '&nbsp;نو، اے د بنى اِسرائيلو خُدايه پاکه، هغه هر څۀ دې رښتيا شى چې د څۀ وعده تا د خپل خِدمت کوونکى يعنې زما د پلار داؤد سره کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8464, '1 Kings 8:27', '1 Kings', 8, 27, '&nbsp;خو اے خُدايه پاکه، تۀ په زمکه باندې نۀ شې اوسېدې، ځکه چې ټول آسمان ستا د ځائېدو دپاره کافى نۀ دے، نو دا کور به څنګه کافى وى چې کوم ما جوړ کړے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8465, '1 Kings 8:28', '1 Kings', 8, 28, '&nbsp;خو اے مالِکه خُدايه زما خُدايه پاکه، زۀ ستا خِدمت کوونکے يم. زما دُعا واوره او زۀ چې کوم سوال کوم نو هغه منظور کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8466, '1 Kings 8:29', '1 Kings', 8, 29, '&nbsp;خو په دې کور شپه او ورځ نظر وساته، دا ځائ چې تا د عبادت دپاره خوښ کړے دے. مخ مې دې کور ته کړو او زما سوال واوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8467, '1 Kings 8:30', '1 Kings', 8, 30, '&nbsp;د خپل خِدمت کوونکى دُعا او د خپلو بنى اِسرائيلو خلقو دُعا واوره په هغه وخت کښې چې کله هغوئ دې ځائ ته مخ کوى. په آسمان کښې په خپل کور کښې زمونږ سوال اوره او مونږ معاف کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8468, '1 Kings 8:31', '1 Kings', 8, 31, '&nbsp;کله چې په يو کس اِلزام ولګى چې د بل چا سره يې بد کړى دى او په دې کور کښې ستا قربان‌ګاه ته راوستلے شى چې قسم وکړى چې هغه بې‌ګناه دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8469, '1 Kings 8:32', '1 Kings', 8, 32, '&nbsp;نو اے مالِکه خُدايه، په آسمان کښې اوره او د خپلو خِدمت کوونکو عدالت کوه. مجرم له هم هغه شان سزا ورکوه چې څنګه يې حقدار وى او چې څوک بې‌ګناه وى نو د هغۀ صفائى کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8470, '1 Kings 8:33', '1 Kings', 8, 33, '&nbsp;کله چې ستا خلق بنى اِسرائيليان د خپلو دشمنانو نه شکست وخورى ځکه چې هغوئ به ستا خِلاف ګناه کړې وى، چې کله هغوئ تا ته راوګرځى او بيا په تا توکل وکړى او په دې کور کښې تا ته سوال وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8471, '1 Kings 8:34', '1 Kings', 8, 34, '&nbsp;نو په آسمان کښې د هغوئ سوال اوره. د خپلو خلقو ګناهونه معاف کوه او هغه مُلک ته يې واپس راوله چې کوم تا د هغوئ پلار نيکۀ له ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8472, '1 Kings 8:35', '1 Kings', 8, 35, '&nbsp;کله چې تۀ باران ايسار کړې ځکه چې ستا خلقو به ستا خِلاف ګناه کړې وى او بيا چې کله هغوئ توبه وباسى او مخ دې کور ته کړى، ځکه چې تا سزا ورکړې وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8473, '1 Kings 8:36', '1 Kings', 8, 36, '&nbsp;نو په آسمان کښې د هغوئ سوال اوره. د بادشاه او د خپلو خلقو بنى اِسرائيلو ګناهونه معاف کوه. هغوئ ته د عمل نېغه لاره ښايه. اے مالِکه خُدايه، د خپلو خلقو په دې زمکه باندې باران وروه، کوم چې تا خپلو خلقو له په پوخ ميراث کښې ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8474, '1 Kings 8:37', '1 Kings', 8, 37, '&nbsp;کله چې په مُلک کښې قحط يا وبا وى، يا په سوزېدونکې هواګانو او يا د قحطۍ مُولخانو په ذريعه فصلونه تباه شى، يا ستا د خلقو په ښارونو باندې دشمنانو حمله کړې وى، يا په هغوئ باندې څۀ افت يا بيمارى راشى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8475, '1 Kings 8:38', '1 Kings', 8, 38, '&nbsp;نو بيا د هغوئ دُعاګانې اوره. کۀ ستا خلقو بنى اِسرائيلو نه څوک هم د زړۀ د اخلاصه توبه وباسى او خپل لاسونه د دُعا دپاره دې کور ته اوچت کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8476, '1 Kings 8:39', '1 Kings', 8, 39, '&nbsp;نو د هغوئ سوال اوره. د هغوئ دُعا په آسمان کښې په خپل کور کښې اوره، هغوئ معاف کوه او مدد يې کوه. يواځې تۀ د انسان د زړۀ په خيالونو پوهېږې. د هر چا سره هغه سلوک کوه چې څنګه يې حقدار وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8477, '1 Kings 8:40', '1 Kings', 8, 40, '&nbsp;نو ستا خلق به ټول عُمر ستا تابعدارى کوى چې په هغه مُلک کښې اوسيږى چې تا د هغوئ پلار نيکۀ له ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8478, '1 Kings 8:43', '1 Kings', 8, 43, '&nbsp;نو د هغۀ سوال اوره. په آسمان کښې چرته چې تۀ اوسېږې د هغۀ سوال اوره او چې څۀ غواړى نو هغه ورله ورکړه، نو داسې د دُنيا ټول قومونه به تا وپېژنى او ستا تابعدارى به کوى، لکه چې ستا خلق بنى اِسرائيليان يې کوى. نو هغوئ ته به پته ولګى چې دا کور چې کوم ما جوړ کړے دے هغې پورې ستا نوم تړلے شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8479, '1 Kings 8:44', '1 Kings', 8, 44, '&nbsp;کله چې تۀ خپلو خلقو له د تلو حُکم ورکړې چې د خپلو دشمنانو خِلاف جنګ وکړى او هغوئ تا ته سوال وکړى، چې دې ښار ته چې تا خوښ کړے دے او چې دې کور ته يې مخ وى چې ستا د عبادت دپاره ما جوړ کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8480, '1 Kings 8:45', '1 Kings', 8, 45, '&nbsp;نو د هغوئ سوال اوره. په آسمان کښې هغوئ ته غوږ اېږده او هغوئ له فتح ورکوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8481, '1 Kings 8:46', '1 Kings', 8, 46, '&nbsp;کله چې ستا خلق ستا خِلاف ګناه وکړى (داسې هيڅ څوک هم نشته چې ګناه نۀ کوى)، او تۀ په غصه کښې هغوئ پرېږدې چې دشمن شکست ورکړى او هغوئ يې خپل مُلک ته قېديان بوځى، کۀ هغه مُلک لرې هم وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8482, '1 Kings 8:47', '1 Kings', 8, 47, '&nbsp;خو د خپلو خلقو سوال اوره. کۀ هغوئ د جلاوطنۍ په مُلک کښې توبه وباسى او تا ته سوال وکړى او دا اِقرار وکړى، چې هغوئ څومره ګناهګار او بدعمله دى، نو اے مالِکه خُدايه، د هغوئ سوال اوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8483, '1 Kings 8:48', '1 Kings', 8, 48, '&nbsp;خو کۀ د دشمن په مُلک کښې هغوئ په رښتيا او خلوص سره توبه وباسى او تا ته سوال وکړى او مخ يې دې مُلک ته وى چې تا زمونږ پلار نيکۀ له ورکړے دے، هغه ښار چې تا خوښ کړے دے او دا کور چې ما ستا دپاره جوړ کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8484, '1 Kings 8:49', '1 Kings', 8, 49, '&nbsp;نو د هغوئ دُعا ته غوږ نيسه. په آسمان کښې په خپل کور کښې د هغوئ سوال اوره او د هغوئ مدد کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8485, '1 Kings 8:50', '1 Kings', 8, 50, '&nbsp;د خپلو خلقو ټول ګناهونه او ستا خِلاف سرکشۍ معاف کوه او هغه دشمنان ورباندې مِهربانه کړه، کومو چې جلاوطن کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8486, '1 Kings 8:51', '1 Kings', 8, 51, '&nbsp;هغوئ بيا هم ستا خپل خلق دى، هغه ميراث، چې تا د مِصر مُلک نه راوويستل چې سم سور اور وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8487, '1 Kings 8:52', '1 Kings', 8, 52, '&nbsp;مالِکه خُدايه، تۀ په بنى اِسرائيلو او ستا خِدمت کوونکى باندې همېشه د رحم نظر کوه او چې کله هم هغوئ تا ته د مدد چغه وهى نو د هغوئ سوال اوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8488, '1 Kings 8:53', '1 Kings', 8, 53, '&nbsp;تا هغوئ د ټولو قومونو نه خوښ کړل چې ستا خپل خلق شى لکه څنګه چې تا د خپل خِدمت کوونکى موسىٰ په ذريعه هغوئ ته فرمائيلى وُو کله چې تا زمونږ پلار نيکۀ د مِصر نه راويستل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8489, '1 Kings 8:54', '1 Kings', 8, 54, '&nbsp;کله چې سليمان مالِک خُدائ ته دُعا ختمه کړه، نو هغه د قربان‌ګاه په وړاندې پاڅېدو، چرته چې په سجده شوے وو او لاسونه يې آسمان ته اوچت کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8490, '1 Kings 8:55', '1 Kings', 8, 55, '&nbsp;هغه پاڅېدو او په اوچت آواز يې د بنى اِسرائيلو ټول قوم دپاره د خُدائ پاک نه برکت وغوښتو چې هلته راغوڼد وُو. او هغۀ وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8491, '1 Kings 8:56', '1 Kings', 8, 56, '&nbsp;”د مالِک خُدائ ثناء صِفت دې وى چې هغۀ خپلو خلقو له امن ورکړے دے، لکه څنګه چې هغۀ وعده کړې وه. هغه په خپلو ټولو پَخو وعدو کښې پاتې نۀ دے راغلے کومې يې چې د خپل خِدمت کوونکى موسىٰ په ذريعه يې کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8492, '1 Kings 8:57', '1 Kings', 8, 57, '&nbsp;مالِک خُدائ زمونږ خُدائ پاک دې زمونږ مل وى، لکه څنګه چې هغه زمونږ د پلار نيکۀ مل وو، هغه دې زمونږ نه هيڅکله نۀ ځى او نۀ دې مونږ پرېږدى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8493, '1 Kings 8:58', '1 Kings', 8, 58, '&nbsp;چې هغه زمونږ ارادې بدلې کړى، نو چې مونږ هر څۀ کوُو د هغۀ مرضى پوره کوُو او د هغۀ ټول قانون او حُکمونه منو چې زمونږ پلار نيکۀ له يې ورکړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8494, '1 Kings 8:59', '1 Kings', 8, 59, '&nbsp;مالِک خُدائ زمونږ خُدائ پاک دې هر وخت دا خبرې يادې ساتى چې ما هغۀ ته کړې دى. هغه دې د خپلو خلقو بنى اِسرائيلو او زما مدد وکړى، لکه څنګه چې د هرې ورځې ضرورتونه لرو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8495, '1 Kings 8:60', '1 Kings', 8, 60, '&nbsp;نو د دُنيا ټولو قومونو ته به پته ولګى چې صِرف مالِک خُدائ، خُدائ پاک دے او بل يو خُدائ هم نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8496, '1 Kings 8:61', '1 Kings', 8, 61, '&nbsp;تاسو يعنې د هغۀ خلق دې د مالِک خُدائ زمونږ د خُدائ پاک پوره وفادار وى، چې د هغۀ په ټول قانون او حُکمونو باندې هم هغه شان عمل کوئ لکه څنګه چې نن کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8497, '1 Kings 8:62', '1 Kings', 8, 62, '&nbsp;سليمان بادشاه او د هغۀ سره ټولو بنى اِسرائيلو مالِک خُدائ ته نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8498, '1 Kings 8:63', '1 Kings', 8, 63, '&nbsp;سليمان دوويشت زره څاروى او يو لاک شل زره ګډې د سلامتۍ نذرانې په توګه پېش کړې. نو داسې بادشاه او د بنى اِسرائيلو ټولو خلقو د مالِک خُدائ کور وقف کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8499, '1 Kings 8:64', '1 Kings', 8, 64, '&nbsp;هم په هغه ورځ هغۀ د دربار مرکزى حِصه هم وقف کړه، کومه حِصه چې د مالِک خُدائ کور ته مخامخ وه. هغۀ هلته پوره سوزېدونکې نذرانې، د غلې نذرانې، او د سلامتۍ نذرانو دپاره د څاروو وازګه پېش کړه. هغۀ داسې په دې وجه وکړل چې د زېړو قربان‌ګاه د دې ټولو نذرانو دپاره ډېره وړه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8500, '1 Kings 8:65', '1 Kings', 8, 65, '&nbsp;سليمان بادشاه او د بنى اِسرائيلو ټولو خلقو اووۀ ورځې د جونګړو اختر وکړو. هلته يوه لويه ګڼه وه چې په شمال کښې د حمات درې نه واخله په جنوب کښې د مِصر سرحد پورې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');